function useServiceScrollReveal(pageClass:string){
 React.useEffect(()=>{
  const root=document.querySelector(`.${pageClass}`);
  if(!root || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const targets=root.querySelectorAll<HTMLElement>('.svc-section, .svc-final');
  targets.forEach((target)=>target.classList.add('svc-scroll-reveal'));
  if(!('IntersectionObserver' in window)){targets.forEach((target)=>target.classList.add('svc-is-visible'));return;}
  const observer=new IntersectionObserver((entries)=>{
   entries.forEach((entry)=>{
    if(entry.isIntersecting){entry.target.classList.add('svc-is-visible');observer.unobserve(entry.target);}
   });
  },{threshold:0.12,rootMargin:'0px 0px -45px 0px'});
  targets.forEach((target)=>observer.observe(target));
  return ()=>observer.disconnect();
 },[pageClass]);
}

